using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Data;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;

namespace Jamera.Items.Manufacturers
{
    public partial class Manufacturers : DevExpress.XtraEditors.XtraUserControl
    {
        //String Message_Title = "Error Alert";
        public Manufacturers()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void Manufacturers_List_Load(object sender, EventArgs e)
        {
            search_inp.Focus();
        }

        public void Refresh_Grid_Data()
        {
            search_inp.Text = null;
            this.Enabled = false;
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            list.Update();
            this.Enabled = true;
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            search_inp.Focus();
            New_Manufacturer new_manufac = new New_Manufacturer();
            new_manufac.manufacturers = this;
            new_manufac.Do_Refresh = true;
            new_manufac.Show(this);
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            Refresh_Grid_Data();
            search_inp.Focus();
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Manufacturer manufacturer = new Manufacturer();
                manufacturer.Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0]));
                manufacturer.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[1]));
                manufacturer.Description = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[2]));
                Edit_Manufacturer edit_manufac = new Edit_Manufacturer(manufacturer);
                edit_manufac.manufacturers = this;
                edit_manufac.Do_Refresh = true;
                edit_manufac.ShowDialog(this);
            }
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            gridView1.ApplyFindFilter(search_inp.Text);
        }

        public void Controls_List(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.F1 || e.KeyCode == Keys.Down)
            {
                gridView1.Focus();
            }
            if ((e.KeyCode == Keys.F2 || e.KeyCode == Keys.Enter) && list.ContainsFocus == true)
            {
                if (gridView1.DataRowCount > 0)
                {
                    Manufacturer manufacturer = new Manufacturer();
                    manufacturer.Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0]));
                    manufacturer.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[1]));
                    manufacturer.Description = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[2]));
                    Edit_Manufacturer edit_manufac = new Edit_Manufacturer(manufacturer);
                    edit_manufac.manufacturers = this;
                    edit_manufac.Do_Refresh = true;
                    edit_manufac.ShowDialog(this);
                }
            }
            if (e.KeyCode == Keys.F3 || (e.Control && e.KeyCode == Keys.F))
            {
                search_inp.Focus();
            }
            if (e.KeyCode == Keys.F6 || (e.Control && e.KeyCode == Keys.N))
            {
                search_inp.Focus();
                New_Manufacturer new_manufac = new New_Manufacturer();
                new_manufac.manufacturers = this;
                new_manufac.Do_Refresh = true;
                new_manufac.Show(this);
            }
            if (e.KeyCode == Keys.F5 || (e.Control && e.KeyCode == Keys.R))
            {
                Refresh_Grid_Data();
                search_inp.Focus();
            }

        }

        private void search_inp_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }

        private void list_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }
    }
}
